// Normalize phone to E.164, validate name/phone/consent, flag in-file duplicates
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const name = (r.name || '').trim();
  let digits = String(r.phone || '').replace(/[^\d+]/g, '');
  let phone = null;
  if (/^\+91[6-9]\d{9}$/.test(digits)) phone = digits;
  else if (/^91[6-9]\d{9}$/.test(digits)) phone = '+' + digits;
  else if (/^0?[6-9]\d{9}$/.test(digits)) phone = '+91' + digits.slice(-10);
  // anything else (wrong length, landline, foreign) is NOT guessed

  const consent = ['yes', 'true', '1', 'y'].includes(String(r.consent || '').trim().toLowerCase());

  let reason = null;
  if (!name) reason = 'missing_name';
  else if (!phone) reason = 'invalid_phone';
  else if (!consent) reason = 'missing_consent';
  else if (seen.has(phone)) reason = 'duplicate_in_file';

  if (phone && !reason) seen.add(phone);

  out.push({
    json: {
      valid: !reason,
      reason,
      name,
      phone_e164: phone,
      email: (r.email || '').trim() || null,
      source: r.source || 'csv',
      property_interest: r.property_interest || null,
      budget: r.budget || null,
      location: r.location || null,
      consent,
      consent_source: r.consent_source || null,
      raw: r
    }
  });
}
return out;

const items = $input.all();
let created = 0, updated = 0, dupesInFile = 0, invalid = 0;
for (const item of items) {
  const j = item.json;
  if (j.reason === 'duplicate_in_file') { dupesInFile++; continue; }
  if (j.reason) { invalid++; continue; }
  if (j.inserted === true) created++;
  else if (j.inserted === false) updated++;
}
return [{ json: { created, updated, dupesInFile, invalid } }];
